CREATE TABLE public.wheel_prizes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL CHECK (length(label) BETWEEN 1 AND 80), amount numeric NOT NULL DEFAULT 0 CHECK (amount >= 0 AND amount <= 1000000), weight numeric NOT NULL DEFAULT 1 CHECK (weight >= 0 AND weight <= 100), sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.wheel_prizes TO authenticated; GRANT ALL ON public.wheel_prizes TO service_role;
ALTER TABLE public.wheel_prizes ENABLE ROW LEVEL SECURITY;
CREATE POLICY wheel_prizes_read ON public.wheel_prizes FOR SELECT TO authenticated USING (true);
CREATE POLICY wheel_prizes_admin ON public.wheel_prizes FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.wheel_rounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), is_open boolean NOT NULL DEFAULT true, prizes jsonb NOT NULL);
GRANT SELECT ON public.wheel_rounds TO authenticated; GRANT ALL ON public.wheel_rounds TO service_role;
ALTER TABLE public.wheel_rounds ENABLE ROW LEVEL SECURITY;
CREATE POLICY wheel_rounds_read ON public.wheel_rounds FOR SELECT TO authenticated USING (true);
CREATE UNIQUE INDEX wheel_one_open_round ON public.wheel_rounds ((is_open)) WHERE is_open;
CREATE TABLE public.wheel_assignments (round_id uuid NOT NULL REFERENCES public.wheel_rounds(id), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, prize_id uuid NOT NULL, PRIMARY KEY(round_id,user_id));
GRANT SELECT ON public.wheel_assignments TO authenticated; GRANT ALL ON public.wheel_assignments TO service_role;
ALTER TABLE public.wheel_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY wheel_assignments_admin ON public.wheel_assignments FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.wheel_spins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), round_id uuid NOT NULL REFERENCES public.wheel_rounds(id), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, prize_id uuid NOT NULL, label text NOT NULL, amount numeric NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(round_id,user_id));
GRANT SELECT ON public.wheel_spins TO authenticated; GRANT ALL ON public.wheel_spins TO service_role;
ALTER TABLE public.wheel_spins ENABLE ROW LEVEL SECURITY;
CREATE POLICY wheel_spins_read ON public.wheel_spins FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.publication_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '', share_url text NOT NULL CHECK(share_url ~ '^https?://'), reward numeric NOT NULL DEFAULT 0 CHECK(reward>=0 AND reward<=1000000), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.publication_tasks TO authenticated; GRANT ALL ON public.publication_tasks TO service_role;
ALTER TABLE public.publication_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY publication_tasks_read ON public.publication_tasks FOR SELECT TO authenticated USING(is_active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY publication_tasks_admin ON public.publication_tasks FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.task_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES public.publication_tasks(id), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, links text[] NOT NULL, proof_image text NOT NULL CHECK(length(proof_image)<=1100000), reward numeric NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), admin_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(task_id,user_id));
GRANT SELECT ON public.task_submissions TO authenticated; GRANT ALL ON public.task_submissions TO service_role;
ALTER TABLE public.task_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY task_submissions_read ON public.task_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX task_submissions_pending ON public.task_submissions(status,created_at);
CREATE OR REPLACE FUNCTION public.open_wheel_round() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE snapshot jsonb; rid uuid; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF;
PERFORM pg_advisory_xact_lock(817264);
SELECT jsonb_agg(jsonb_build_object('id',id,'label',label,'amount',amount,'weight',weight) ORDER BY sort_order,id) INTO snapshot FROM public.wheel_prizes WHERE is_active;
IF snapshot IS NULL OR jsonb_array_length(snapshot)<2 OR jsonb_array_length(snapshot)>12 THEN RAISE EXCEPTION 'أضف بين جائزتين و12 جائزة'; END IF;
IF (SELECT sum((v->>'weight')::numeric) FROM jsonb_array_elements(snapshot) v)<>100 THEN RAISE EXCEPTION 'يجب أن يكون مجموع نسب الفوز 100%%'; END IF;
UPDATE public.wheel_rounds SET is_open=false WHERE is_open;
INSERT INTO public.wheel_rounds(prizes) VALUES(snapshot) RETURNING id INTO rid; RETURN rid; END $$;
CREATE OR REPLACE FUNCTION public.assign_wheel_prize(_round_id uuid,_user_id uuid,_prize_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.wheel_rounds; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF;
SELECT * INTO r FROM public.wheel_rounds WHERE id=_round_id FOR UPDATE;
IF r.id IS NULL OR NOT r.is_open THEN RAISE EXCEPTION 'الجولة مغلقة'; END IF;
PERFORM 1 FROM public.profiles WHERE id=_user_id AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'الحساب غير مفعل'; END IF;
IF EXISTS(SELECT 1 FROM public.wheel_spins WHERE round_id=_round_id AND user_id=_user_id) THEN RAISE EXCEPTION 'الحساب استخدم محاولته'; END IF;
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.prizes) v WHERE (v->>'id')::uuid=_prize_id) THEN RAISE EXCEPTION 'الجائزة غير موجودة'; END IF;
INSERT INTO public.wheel_assignments(round_id,user_id,prize_id) VALUES(_round_id,_user_id,_prize_id) ON CONFLICT(round_id,user_id) DO UPDATE SET prize_id=EXCLUDED.prize_id; END $$;
CREATE OR REPLACE FUNCTION public.spin_reward_wheel(_round_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); r public.wheel_rounds; chosen uuid; v jsonb; prize jsonb; threshold numeric; running numeric:=0; existing public.wheel_spins; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'يرجى تسجيل الدخول'; END IF;
SELECT * INTO r FROM public.wheel_rounds WHERE id=_round_id FOR SHARE;
IF r.id IS NULL THEN RAISE EXCEPTION 'الجولة غير موجودة'; END IF;
PERFORM 1 FROM public.profiles WHERE id=uid AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'العجلة للحسابات المفعلة فقط'; END IF;
SELECT * INTO existing FROM public.wheel_spins WHERE round_id=_round_id AND user_id=uid;
IF existing.id IS NOT NULL THEN RETURN to_jsonb(existing); END IF;
IF NOT r.is_open OR COALESCE((SELECT value FROM public.settings WHERE key='wheel_visible'),'false')<>'true' THEN RAISE EXCEPTION 'العجلة غير متاحة'; END IF;
SELECT prize_id INTO chosen FROM public.wheel_assignments WHERE round_id=_round_id AND user_id=uid;
IF chosen IS NOT NULL THEN SELECT value INTO prize FROM jsonb_array_elements(r.prizes) WHERE (value->>'id')::uuid=chosen;
ELSE threshold:=random()*100; FOR v IN SELECT value FROM jsonb_array_elements(r.prizes) LOOP running:=running+(v->>'weight')::numeric; IF threshold<running THEN prize:=v; EXIT; END IF; END LOOP; END IF;
IF prize IS NULL THEN RAISE EXCEPTION 'إعداد الجوائز غير مكتمل'; END IF;
INSERT INTO public.wheel_spins(round_id,user_id,prize_id,label,amount) VALUES(_round_id,uid,(prize->>'id')::uuid,prize->>'label',(prize->>'amount')::numeric) RETURNING * INTO existing;
UPDATE public.profiles SET balance=balance+existing.amount WHERE id=uid;
INSERT INTO public.notifications(target_user_id,message) VALUES(uid,'جائزة العجلة: '||existing.label||' — '||existing.amount||' USDT');
RETURN to_jsonb(existing); END $$;
CREATE OR REPLACE FUNCTION public.submit_publication_task(_task_id uuid,_links text[],_proof_image text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); t public.publication_tasks; sid uuid; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'يرجى تسجيل الدخول'; END IF;
SELECT * INTO t FROM public.publication_tasks WHERE id=_task_id AND is_active FOR SHARE; IF t.id IS NULL THEN RAISE EXCEPTION 'المهمة غير متاحة'; END IF;
IF array_length(_links,1) IS NULL OR array_length(_links,1)>10 OR EXISTS(SELECT 1 FROM unnest(_links) l WHERE l !~ '^https?://' OR length(l)>2048) THEN RAISE EXCEPTION 'أدخل روابط نشر صحيحة'; END IF;
IF _proof_image IS NULL OR length(_proof_image)>1100000 OR _proof_image !~ '^data:image/jpeg;base64,[A-Za-z0-9+/=]+$' THEN RAISE EXCEPTION 'صورة الإثبات غير صالحة أو كبيرة'; END IF;
INSERT INTO public.task_submissions(task_id,user_id,links,proof_image,reward) VALUES(t.id,uid,_links,_proof_image,t.reward) ON CONFLICT(task_id,user_id) DO UPDATE SET links=EXCLUDED.links,proof_image=EXCLUDED.proof_image,reward=EXCLUDED.reward,status='pending',admin_note='',processed_at=NULL,created_at=now() WHERE task_submissions.status='rejected' RETURNING id INTO sid;
IF sid IS NULL THEN RAISE EXCEPTION 'سبق إرسال هذه المهمة'; END IF; RETURN sid; END $$;
CREATE OR REPLACE FUNCTION public.review_publication_task(_submission_id uuid,_approve boolean,_note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.task_submissions; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF;
SELECT * INTO s FROM public.task_submissions WHERE id=_submission_id FOR UPDATE;
IF s.id IS NULL OR s.status<>'pending' THEN RAISE EXCEPTION 'تمت معالجة هذا الطلب'; END IF;
IF _approve THEN UPDATE public.profiles SET balance=balance+s.reward WHERE id=s.user_id; END IF;
UPDATE public.task_submissions SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,admin_note=left(COALESCE(_note,''),1000),processed_at=now() WHERE id=s.id;
INSERT INTO public.notifications(target_user_id,message) VALUES(s.user_id,CASE WHEN _approve THEN 'تم قبول المهمة وإضافة '||s.reward||' USDT إلى رصيدك' ELSE 'تم رفض إثبات المهمة: '||COALESCE(_note,'') END); END $$;
REVOKE ALL ON FUNCTION public.open_wheel_round(), public.assign_wheel_prize(uuid,uuid,uuid), public.spin_reward_wheel(uuid), public.submit_publication_task(uuid,text[],text), public.review_publication_task(uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.open_wheel_round(), public.assign_wheel_prize(uuid,uuid,uuid), public.spin_reward_wheel(uuid), public.submit_publication_task(uuid,text[],text), public.review_publication_task(uuid,boolean,text) TO authenticated;